  ui_story_5080_50800201_17_dialog_content = "จริงๆ แล้ว เรามาที่นี่เพื่อภารกิจพิเศษ... คุณรู้จักอิคลิพไซท์ที่ไม่ธรรมดาหรือเป็นเอกลักษณ์ในทะเลทรายนี้ไหม?",
  ui_story_5080_50800201_18_dialog_content = "เอ๊ะ? เช่นอะไรบ้าง...?",
  ui_story_5080_50800201_19_dialog_content = "เอ่อ, ให้ฉันคิดดู... อาจจะเป็นอันที่ดูเหมือนกำลังไหม้? หรืออันที่อยู่รอบ ๆ ภูเขาไฟ?",
  ui_story_5080_50800201_20_dialog_content = "คุณพูดอะไรน่ะ? มีอิคลิพไซท์เต็มไปหมดรอบ ๆ ภูเขาไฟนะ.",
  ui_story_5080_50800201_21_dialog_content = "ใช่ แต่อิคลิพไซท์เหล่านี้ถูกดึงดูดโดยภูเขาไฟโดยเฉพาะ และพวกมันยังสามารถใช้พลังของลาวาได้ด้วย",
  ui_story_5080_50800201_22_dialog_content = "พวกมันแข็งแรงอย่างผิดปกติ และพวกมันทิ้งร่องรอยการเคลื่อนไหวที่ชัดเจนไว้ทุกที่ที่พวกมันไป",
  ui_story_5080_50800201_23_dialog_content = "คุณสามารถคิดถึง Eclipsites ที่เหมาะสมได้หรือไม่?",
  ui_story_5080_50800201_24_dialog_content = "อิคลิพไซท์ลาวา... ไม่เชื่อได้ มันผ่านมากว่าสิบปีแล้ว...",
  ui_story_5080_50800201_25_dialog_content = "ดังนั้นคุณรู้เรื่องเกี่ยวกับพวกเขาสินะ?",
  ui_story_5080_50800201_26_dialog_content = "กรุณาบอกเราทุกอย่างที่คุณรู้ ตอนนี้เราต้องการข้อมูลเกี่ยวกับพวกเขามากที่สุดเท่าที่จะทำได้",
  ui_story_5080_50800201_27_dialog_content = "เท่าที่คนส่วนใหญ่เห็น สิ่งเหล่านี้เป็นเรื่องที่ผ่านมานานแล้ว มันยังมีความเกี่ยวข้องกับครอบครัวของเราอีกด้วย...",
  ui_story_5080_50800201_28_dialog_content = "แต่เนื่องจากมันสำคัญกับพวกคุณมาก ฉันคิดว่าฉันสามารถบอกเรื่องนี้ให้พวกคุณฟังได้นะ",
  ui_story_5080_50800201_29_dialog_content = "ฉันรู้เรื่องเกี่ยวกับอิคลิพไซท์ที่คุณกำลังหา... หรือกล่าวอีกอย่างหนึ่งคือ สมาชิกเก่า ๆ ของ <color=#FFB400>เรดีเซล เวรนช์</color> มีการแค้นเลือดกับพวกเขา",
  ui_story_5080_50800201_30_dialog_content = "หมายความว่าไงเหรอ",
  ui_story_5080_50800201_31_dialog_content = "เรื่องราวนั้นเกิดขึ้นในช่วง<color=#FFB400>วิกฤตดาร์กโอเวอร์</color> ในเวลานั้น ฉันเพียงแค่เด็กผู้ชายที่ทำงานเป็นผู้ส่งข้อความให้กับผู้นำของเรดีเซล เวรนช์",
  ui_story_5080_50800201_32_dialog_content = "วันหนึ่ง อิคลิพไซท์ได้พัดผ่าบ้านเก่าของเราเหมือนพายุทราย และเราไม่มีทางเลือกอื่นนอกจากต้องทิ้งมันไป",
  ui_story_5080_50800201_33_dialog_content = "เพื่อซื้อเวลาให้เราหนี ผู้นำของเราได้พานักสู้ที่ดีที่สุดของเราไปปกป้องด้านหลัง",
  ui_story_5080_50800201_34_dialog_content = "ฉันยังจำสิ่งที่ฉันเห็นในวันนั้นได้... สัตว์ประหลาดที่แท้จริง ตัวหนึ่งที่ทำให้ทรายที่อยู่ใต้เท้าของมันเป็นแก้วหลอม...",
  ui_story_5080_50800201_35_dialog_content = "ห๊ะ",
  ui_story_5080_50800201_36_dialog_content = "อะไร, ไม่ได้ยินฉันหรอ? ฉันพูดว่า...",
