  ui_story_5080_50800201_40_dialog_content = "PlayerName ระวัง!",
  ui_story_5080_50800201_41_dialog_content = "อ้าว—หยุดเดี๋ยวนี้นะ!",
  ui_story_5080_50800201_42_dialog_content = "อ๊าาาาาาก—",
  ui_story_5080_50800201_43_dialog_content = "ขอโทษนะคะ ที่รัก แต่ไม่มีอะไรที่สามารถหยุดพลังของดนตรีได้!",
  ui_story_5080_50800201_44_dialog_content = "ขอบคุณพระเจ้าสำหรับ<color=#FFB400>นักรบผู้ถูกสาป</color>และพลังที่แสนผิดปกติของเขา!",
  ui_story_5080_50800201_45_dialog_content = "เซต้า? บาร์บาร่าและเจ้าจิ๋วด้วยเหรอ?! พวกเธอทำอะไรกันน่ะ?!",
  ui_story_5080_50800201_46_dialog_content = "คุณเพิ่งเข้าไปชนฐานด้วยรถบรรทุกของคุณ นั่นแหละ...",
