  ui_story_5080_50800201_48_dialog_content = "ห๊ะ!",
  ui_story_5080_50800201_49_dialog_content = "อย่าบอกฉันว่าคุณไม่ได้ยินฉัน, <color=#FFB400>นักรบผู้ถูกสาป</color>?! เสียงฝีเท้าจากดินแดนที่ห่างไกล—",
