  ui_story_5080_50800201_63_dialog_content = "ทหารอิลลูมินาคนหนึ่งที่พยายามล่าเด็ก ๆ ของเรา และบังคับให้พวกเขาขับรถชนเข้าสู่ฐานของเรา...",
  ui_story_5080_50800201_64_dialog_content = "พวกโจรทะเลทรายที่มีความกล้าหาญมาขโมยเพื่อนร่วมอาวุธของฉัน... ฉันจะไม่ปรานีแล้วนะ!",
  ui_story_5080_50800201_65_dialog_content = "กำลังมองหาการต่อสู้หรือเปล่า? ดี! มันเป็นเวลานานมากแล้วที่ฉันไม่ได้โยนหมัดใส่คุณทุกคน!",
