  ui_story_5080_50800202_1_dialog_content = "แมลงบินน่ารำคาญ—ฉันจะบดขยี้พวกเจ้าทุกตัวจนหมด!",
  ui_story_5080_50800202_2_dialog_content = "คุณได้อะไรอีกตอนนี้?",
  ui_story_5080_50800202_3_dialog_content = "อย่าขยับนะ นอกจากว่าคุณอยากถูกยิงขึ้นไปในท้องฟ้า...",
  ui_story_5080_50800202_4_dialog_content = "เธอเพิ่งปลูกวัตถุระเบิดบนฉันเมื่อสักครู่เหรอ? ไม่เลวเลยนะ.",
  ui_story_5080_50800202_5_dialog_content = "ที่ระยะนี้ ไม่มีใครในพวกเราที่จะรอดจากการระเบิดได้",
  ui_story_5080_50800202_6_dialog_content = "และยังดูเหมือนว่าคุณไม่กลัวเลย... ฉันชอบนะ! ตอนนี้ มาดูกันว่าจะเกิดอะไรขึ้นต่อไป!",
  ui_story_5080_50800202_7_dialog_content = "ฉันยินดีที่จะสละชีวิตของฉันถ้ามันหมายความว่าจะสามารถทำลายหัวหน้าของเรดีเซล เวรนช์...",
