  ui_story_5080_50800202_13_dialog_content = "ฮือออ—",
  ui_story_5080_50800202_14_dialog_content = "เราวางอาวุธลงแล้วมาหาคำตอบว่าเกิดอะไรขึ้นกันดีไหม?",
  ui_story_5080_50800202_15_dialog_content = "ฉันคือผู้ที่ได้กระตุ้นสมุนของราชาปีศาจ ฉันจะรับผิดชอบเต็มที่ ดังนั้นก็ปล่อยเพื่อนของฉันไปสิ!",
  ui_story_5080_50800202_16_dialog_content = "...",
  ui_story_5080_50800202_17_dialog_content = "เกิดอะไรขึ้นที่นี่เนี่ย เซต้า?",
  ui_story_5080_50800202_18_dialog_content = "ทุกอย่างเริ่มต้นจากตำนานของเซต้า นักรบที่ยิ่งใหญ่ที่สุดในตลอดกาล—",
  ui_story_5080_50800202_19_dialog_content = "หลังจากที่ฝึกฝนการวิ่งอย่างหนักหนา ฉันก็ยังไม่สามารถเอาชนะแม่มดแห่งสนามแข่งในการแข่งความเร็วได้",
  ui_story_5080_50800202_20_dialog_content = "ฉันแน่ใจว่ามันต้องเกี่ยวข้องกับการที่เธอมีเคเลสไทต์คนสุดท้ายเป็นพันธมิตร ดังนั้นฉันจึงตัดสินใจที่จะหาพันธมิตรที่มีพลังให้เป็นของตัวเอง",
  ui_story_5080_50800202_21_dialog_content = "นั่นคือเวลาที่ฉันพบว่าบาร์บาร่า <color=#FFB400>นักร้องซูเปอร์โนวา</color> และเรจินากำลังทะเลาะกันเกี่ยวกับการแข่งขันร้องเพลงบางประเภท!",
  ui_story_5080_50800202_22_dialog_content = "\"โอ้ นักรบที่ยิ่งใหญ่เซต้า โปรดยืมแรงให้ฉันหน่อย!\"",
  ui_story_5080_50800202_23_dialog_content = "\"ด้วยคุณอยู่ข้างๆฉัน ฉันสามารถรวบรวมฝูงชนมากกว่าที่เรจินาจะเคยหวังไว้! ผู้ชมของฉันคือแหล่งพลังของฉัน!\"",
  ui_story_5080_50800202_24_dialog_content = "\"ฟังดูเหมือนจะสนุกนะ! แค่อย่าลืมฉัน: <color=#FFB400>อาวุธมืออาชีพ</color> ที่ภักดีต่อเซต้า!\"",
  ui_story_5080_50800202_25_dialog_content = "อ้าว! พวกเขาน่าจะเป็นพันธมิตรที่ฉันกำลังหาหรือเปล่า? พวกเขาคงถูกดึงดูดโดยความอัปรีย์ของฉัน!",
  ui_story_5080_50800202_26_dialog_content = "และดังนั้น เราก็เริ่มเดินทางอันยิ่งใหญ่ไปทัวร์ทะเลทรายที่รุนแรงและรวบรวมแฟน ๆ มากขึ้นอีก!",
  ui_story_5080_50800202_27_dialog_content = "และด้วยการประดิษฐ์ล่าสุดและที่ยิ่งใหญ่ที่สุดของเรา, <color=#FFB400>Rediesel Super Idol-mobile</color>, เราขี่ลงสู่สนามรบ—",
  ui_story_5080_50800202_28_dialog_content = "อะไรนะ? ช่วยเข้าสู่ส่วนสำคัญได้ไหมครับ?!",
  ui_story_5080_50800202_29_dialog_content = "... เฮ้อ.",
  ui_story_5080_50800202_30_dialog_content = "ขณะที่พวกเราเดินทางผ่านทะเลทรายด้วยเพลงที่ลุกเป็นไฟในหัวใจ เราก็สังเกตเห็นบางสิ่งอย่างกะทันหัน!",
  ui_story_5080_50800202_31_dialog_content = "เหยี่ยวเดียวดายนั่งอยู่บนยอดทราย",
  ui_story_5080_50800202_32_dialog_content = "\"ฉันเดาว่าเราน่าจะใช้ตัวเล็กน้อยนี้สำหรับการส่องสว่างหรือเสียงได้นะ!\"",
  ui_story_5080_50800202_33_dialog_content = "นั่นคือคำพูดของอาจารย์ผู้ครอบครองอาวุธของฉัน—แต่ฉันสามารถเห็นแรงความเข้มของมันด้วยตัวเอง",
  ui_story_5080_50800202_34_dialog_content = "ดังนั้นฉันจึงตัดสินใจนำนกอินทรีมาเป็นสมาชิกในปาร์ตี้ของเรา!",
  ui_story_5080_50800202_35_dialog_content = "แต่ไม่นานหลังจากนั้น มีสิ่งมีชีวิตที่ชั่วร้ายมาไล่ตามอินทรี มันไม่ยอมหยุดยั้งในการไล่ล่า และมันยังโจมตีเราด้วย",
  ui_story_5080_50800202_36_dialog_content = "ยิงของเธอเป็นอันตรายที่สุดที่ฉันเคยเห็น ฉันกลัวจนไม่กล้าหยุดรถ... ฉันหมายถึง ฉันกลัวเพื่อความปลอดภัยของเพื่อนๆของฉัน!",
  ui_story_5080_50800202_37_dialog_content = "เธอพุ่งชนเข้าบ้านเราด้วยความเร็วสูงเหรอ?!",
  ui_story_5080_50800202_38_dialog_content = "ฉ-ฉันเชื่อว่านักรบผู้ถูกสาปจะหยุดพวกเราได้ทันเวลา!",
