  ui_story_5080_50800602_30_dialog_content = "แต่ฉันยังจำชื่อของหน่วยของเธอได้: หน่วย Freebird นั่นเอง ชื่อเดียวกันที่ทำให้ฉันอิจฉานกและความสามารถในการบินอย่างอิสระในท้องฟ้า",
  ui_story_5080_50800602_31_dialog_content = "\"ทีมฟรีเบิร์ด\"?!",
  ui_story_5080_50800602_32_dialog_content = "(นั่นไม่ใช่ชื่อของทีมที่ราเชลกำลังมองหาอยู่ใช่ไหม?)",
  ui_story_5080_50800602_33_dialog_content = "คนนั้น... หนีไปที่ทะเลทรายด้วยหรือ? แล้วก็ไม่ได้เป็นทรยศเท่านั้น ยังไปร่วมมือกับเรดีเซล เวรนช์—",
  ui_story_5080_50800602_34_dialog_content = "คุณผิด, เยริ: ฉันไม่เหมือนคนนั้นเลย อาจจะเป็นคนที่หนีหน้าไร้เกียรติ แต่ฉันไม่ใช่!",
