  ui_story_5080_50800602_36_dialog_content = "ผู้หญิงคนนั้นไม่ได้เป็นคนที่ไม่รู้จักอายหรือทิ้งทีม จนกระทั่งสุดท้าย เธอคือหนึ่งในคนที่ภูมิใจที่สุดที่ฉันเคยรู้จัก",
  ui_story_5080_50800602_37_dialog_content = "ความมุ่นมั่นที่ลุกโชนของเธอมีสีแดงเท่ากับเรดีเซลเวรนช์ที่เธอถืออยู่ในมือ แม้ว่าจะส่งมันให้ซินซาแล้ว แต่มันก็ยังไม่สูญเสียสีสันเลย",
  ui_story_5080_50800602_38_dialog_content = "ถ้านั่นคือสิ่งที่คุณเชื่อ... งั้นฉันมีเรื่องราวที่จะมาแบ่งปันกับคุณ",
