  ui_story_5080_50800602_88_dialog_content = "ด้วยความฉลาดของเธอ ฉันจริงๆหวังว่าเธอคงจะหลบหนีได้ในตอนนั้น... บางทีเธอก็อาจจะสามารถให้คำตอบที่ฉันกำลังหาอยู่ให้ฉันได้",
