  ui_story_5080_50801301_69_dialog_content = "<color=#e8d9bb>เปรี้ยง!</color>",
  ui_story_5080_50801301_70_dialog_content = "คุณกำลังทับฉัน ชายชรา...",
  ui_story_5080_50801301_71_dialog_content = "ดูสิ, นี่ซินซา! นี่คือซินซาจริงๆ! เขายังมีชีวิตอยู่!",
  ui_story_5080_50801301_72_dialog_content = "ซินซา คุณ—",
  ui_story_5080_50801301_73_dialog_content = "ว้าว... ดูที่อิคลิพไซท์ทั้งหมดที่ตายไปนี้... เขาฆ่าพวกมันทั้งหมดด้วยตัวเองหรือเปล่า?",
  ui_story_5080_50801301_74_dialog_content = "แม้จะได้รับบาดเจ็บใหญ่หลังจากตกลงมาที่นี่ทั้งหมด แต่เขาก็ยังสามารถฆ่าพวกเขาได้เยอะเช่นนี้",
  ui_story_5080_50801301_75_dialog_content = "เฮ้ พวกเธอมาแล้วหรอ... ฉันเพิ่งฆ่าไอ้ตัวโตที่นี่...",
  ui_story_5080_50801301_76_dialog_content = "ซินซา?!",
  ui_story_5080_50801301_77_dialog_content = "ซินซา รีบตื่นเถอะ มันตายไปแล้ว ปล่อยมันแล้วมากับเราสิ!",
  ui_story_5080_50801301_78_dialog_content = "ว่าไง? ซินซา?!",
  ui_story_5080_50801301_79_dialog_content = "ฉันไม่ได้กินอย่างดีเมื่อกี้... ตอนนี้ฉันหิวอีกแล้ว...",
  ui_story_5080_50801301_80_dialog_content = "ฉันอยากจะกลับไปทานอาหารกับทุกคน อาหารมันจะอร่อยขึ้นเมื่อทานด้วยกัน...",
  ui_story_5080_50801301_81_dialog_content = "รอย, ฉันง่วงมาก ฉันคงกังวลมากเกินไปในวันที่ผ่านมานี้",
  ui_story_5080_50801301_82_dialog_content = "เราควรกลับไปฉลองชัยชนะกันเถอะ ไม่ควรทำให้คนอื่นรอนานเกินไป...",
  ui_story_5080_50801301_83_dialog_content = "มีอะไรผิดปกติกับเขา? ตรวจสอบดูว่าเขาไม่เป็นไร—อย่าปล่อยให้เขาเป็นลมแบบนี้!",
  ui_story_5080_50801301_84_dialog_content = "... เขาสบายดี เขาแค่เหนื่อยจนหลับไปเอง",
  ui_story_5080_50801301_85_dialog_content = "เขาออกไปหาคนตั้งแต่คืนวาน และกลับมาก็ไม่ค่อยกินอะไรเลย น่าสงสารจริงๆ",
  ui_story_5080_50801301_86_dialog_content = "ฮึ่ม ฉันรู้ว่าหมอนี่ไม่บอบบางขนาดนั้น",
  ui_story_5080_50801301_87_dialog_content = "อีกทั้งฉันเป็นคนเดียวที่ได้รับอนุญาตให้ทุบเขา!",
  ui_story_5080_50801301_88_dialog_content = "มาเถอะ วางเขาไว้บนหลังฉัน",
  ui_story_5080_50801301_89_dialog_content = "เมื่อเขาตื่นแล้วรู้ว่าต้องพึ่งฉัน เขาจะอายมากเลย!",
  ui_story_5080_50801301_90_dialog_content = "งั้นฉันจะมอบเขาให้คุณดูแล และฉันจะนำทาง มาเร็วๆ กลับขึ้น—",
  ui_story_5080_50801301_91_dialog_content = "ประแจของเขาอยู่ที่ไหน?",
  ui_story_5080_50801301_92_dialog_content = "อาจจะเป็นเพราะเขาทำหายตอนที่ล้ม... ฉันต้องหามัน...",
  ui_story_5080_50801301_93_dialog_content = "<color=#e8d9bb>ตึง!</color>",
  ui_story_5080_50801301_94_dialog_content = "ได้ยินอะไรมั้ย?",
  ui_story_5080_50801301_95_dialog_content = "นั่นเสียงลาวาเหรอ?",
  ui_story_5080_50801301_96_dialog_content = "<color=#e8d9bb>ตุ๊ด, ตุ๊ด!</color>",
  ui_story_5080_50801301_97_dialog_content = "อีกแล้ว!",
  ui_story_5080_50801301_98_dialog_content = "...ฝีเท้า! บร็อค, วิ่งเถอะ!",
  ui_story_5080_50801301_99_dialog_content = "<color=#e8d9bb>ตุ๊ด ตุ๊ด ตุ๊ด ตุ๊ด!</color>",
  ui_story_5080_50801301_100_dialog_content = "รีบหนีไป!!!",
  ui_story_5080_50801302_1_dialog_content = "ช่วยด้วย!!!",
  ui_story_5080_50801302_2_dialog_content = "ใครน่ะ",
  ui_story_5080_50801302_3_dialog_content = "นั่นคือใคร?",
  ui_story_5080_50801302_4_dialog_content = "ว้าว! นี่ก็กัปตันอิลลูมินานี่เอง! รอย, มาที่นี่นะ!",
