  ui_story_5080_50801302_6_dialog_content = "<size=45><color=#e8d9bb>ตุ้บ, ตุ้บ, ตุ้บ, ตุ้บ, ตุ้บ, ตุ้บ, ตุ้บ, ตุ้บ, ตุ้บ, ตุ้บ!</color></size>",
  ui_story_5080_50801302_7_dialog_content = "<color=#e8d9bb>คำราม—!</color>",
  ui_story_5080_50801302_8_dialog_content = "Eclipsite?! ไม่... มันคือ<color=#FFB400>เป้าหมาย</color>!",
