  ui_story_5080_50801302_10_dialog_content = "ฉันจะยิงปกป้อง พวกนายรีบหนีไป ที่เหลือกำลังตามมาทันที!",
  ui_story_5080_50801302_11_dialog_content = "รีบเข้า รอย เรา—",
