  ui_story_5080_50801302_13_dialog_content = "คำราม—!",
  ui_story_5080_50801302_14_dialog_content = "ไอ้พวกขี้ขลาด... มันยอมทนรับการโจมตีกว่าจะปล่อยให้เราผ่านไป.",
  ui_story_5080_50801302_15_dialog_content = "อะไรนะ? อิคลิพไซท์นั่นขวางทางหรอ?",
  ui_story_5080_50801302_16_dialog_content = "สิ่งนั้น... มันคืออะไรที่ฆ่า Attar ใช่มั้ย...?",
