  ui_story_5080_50801302_18_dialog_content = "<color=#FFB400>ทอร์นาโด!</color>",
  ui_story_5080_50801302_19_dialog_content = "<color=#e8d9bb>เพดานถูกระเบิดโดยสายฟ้า ทำให้อิคลิพไซท์ตกลงมา แต่การระเบิดทรงพลังอันรุนแรงนี้ยังทำให้ภูเขาไฟร้องเสียงดัง และพื้นดินก็เริ่มสั่นสะเทือนอีกครั้ง</color>",
  ui_story_5080_50801302_20_dialog_content = "พลังนี้... ข่าวไม่ดีนะครับทุกคน—ภูเขาไฟกำลังจะระเบิดแล้ว!",
  ui_story_5080_50801302_21_dialog_content = "เด็กสาว Rediesel, โจมตีต่อไป!",
  ui_story_5080_50801302_22_dialog_content = "แต่นั่นอาจทำให้เกิดการปะทุเขาไฟ",
  ui_story_5080_50801302_23_dialog_content = "มันตื่นขึ้นมาแล้ว ถ้ามันหลุดออกจากที่นี่ คนอื่น ๆ จะอยู่ในอันตราย!",
  ui_story_5080_50801302_24_dialog_content = "ฉันโจมตีมันตรงๆ แต่ฉันไม่รู้สึกว่าฉันทำให้มันเสียหาย... จุดอ่อนของมันอยู่ที่ไหน?",
  ui_story_5080_50801302_25_dialog_content = "กลุ่มนักล่าอินทรีได้สำรวจมันไปแล้ว หนังสือของมันยังไม่ได้ถึงอุณหภูมิจริงของลาวา",
  ui_story_5080_50801302_26_dialog_content = "และสิ่งมีชีวิตทุกชนิดจะอ่อนแอที่สุดเมื่อกำลังรับประทานอาหาร",
  ui_story_5080_50801302_27_dialog_content = "ถ้าเราสามารถดับเปลือกนอกของมันได้ มันอาจพยายามดูดซับพลังงาน แล้วมันจะเปิดเผยจุดอ่อนของมัน!",
  ui_story_5080_50801302_28_dialog_content = "มันชัดเจนว่าใหญ่กว่านี้เมื่อก่อน... แต่มันย่อตัวลงและซ่อนตัวอยู่ที่นี่อย่างสบายๆ มากกว่าสิบปีแล้ว...?",
  ui_story_5080_50801302_29_dialog_content = "<color=#FFB400>การลาดตระเวนความตาย!</color>",
  ui_story_5080_50801302_30_dialog_content = "<color=#FFB400>ทอร์นาโด!</color>",
  ui_story_5080_50801302_31_dialog_content = "<color=#FFB400>น้ำวนเชี่ยวกราก!</color>",
  ui_story_5080_50801302_32_dialog_content = "<color=#FFB400>บุปผาน้ำแข็ง!</color>",
  ui_story_5080_50801302_33_dialog_content = "กรรร!",
