  ui_story_5080_50801302_35_dialog_content = "<color=#e8d9bb>ตูมม!!!</color>",
  ui_story_5080_50801302_36_dialog_content = "โฮ้ย, ผนังพังแล้ว! ลาวากำลังไหลเข้ามา!",
