  ui_story_5080_50801302_40_dialog_content = "เซต้า เราจะชะลอพวกเขาลงก่อน มาถอยกับฉันก่อนนะ!",
  ui_story_5080_50801302_41_dialog_content = "แต่นางเอกไม่สามารถออกจากเวทีได้ในเวลาแบบนี้!",
