  ui_story_5080_50801302_49_dialog_content = "เยริ?",
  ui_story_5080_50801302_50_dialog_content = "ถ้ามันจริงๆ นั้นคือตัวเดียวกันที่ฆ่า Attar... ฉันจะยอมปล่อยมันไปได้อย่างไร?!",
