  ui_story_5080_50801302_76_dialog_content = "อาจจะช้าหน่อย แต่ฉันจะทำเส้นทาง คุณทุกคนระวังด้วยนะ!",
  ui_story_5080_50801302_77_dialog_content = "ทำไมถึงเกิดเรื่องนี้? เราได้สแกนมันไปแล้ว... ทำไมพลังงานของมันยังคงแรงเกินไปอย่างนี้?",
