  ui_story_5080_50801302_85_dialog_content = "กรรร!",
  ui_story_5080_50801302_86_dialog_content = "ฟักไข่ครั้งที่สอง!",
  ui_story_5080_50801302_87_dialog_content = "อย่ามาแตะต้อง Vice อีกเลย!!!",
  ui_story_5080_50801302_88_option_content = "บูสต์พลัง!",
  ui_story_5080_50801302_89_dialog_content = "ลูกนกตัวที่สอง คุณสบายดีไหม? ตื่นได้แล้ว!",
  ui_story_5080_50801302_90_dialog_content = "(ผู้คลั่งไคล้ความมีประสิทธิภาพยอมให้โอกาสโจมตีไวซ์ผ่านไป...)",
  ui_story_5080_50801302_91_dialog_content = "ทำไมฉันถึงรู้สึกมีความสุขขนาดนี้... แม้ว่าหัวของฉันจะปวดเหลือเกิน...?",
