  ui_story_5080_50801401_16_dialog_content = "<size=45>หยุดเถอะ!</size>",
  ui_story_5080_50801401_17_dialog_content = "ไวซ์... ไวซ์... อย่าทำให้ฉันตกใจแบบนี้นะ...",
